import copy
import struct
import zlib

import pytest

from png_chunks import (
    PNG_SIGNATURE,
    PngError,
    build_minimal_png,
    parse_ihdr,
    walk,
)


@pytest.fixture
def rows():
    # 3x2 image: two scanlines of three RGB pixels each
    return [
        bytes([255, 0, 0,   0, 255, 0,   0, 0, 255]),
        bytes([10, 20, 30, 40, 50, 60, 70, 80, 90]),
    ]


@pytest.fixture
def png(rows):
    return build_minimal_png(3, 2, rows)


def test_signature(png):
    assert png[:8] == PNG_SIGNATURE


def test_walk_chunk_sequence_and_crc(png):
    chunks = list(walk(png))
    assert [c[0] for c in chunks] == ["IHDR", "IDAT", "IEND"]
    assert all(crc for _, _, _, crc in chunks)
    # IEND has zero-length data
    itype, ioff, ilen, icrc = chunks[-1]
    assert ilen == 0


def test_flip_byte_in_idat_reports_false_only_for_idat(png):
    corrupted = bytearray(png)
    # locate IDAT via walk and flip the first byte of its data
    for ctype, offset, length, _ in walk(png):
        if ctype == "IDAT":
            data_off = offset + 8  # skip length + type fields
            break
    else:
        pytest.fail("no IDAT found")
    corrupted[data_off] ^= 0xFF
    results = list(walk(bytes(corrupted)))
    by_type = {ctype: crc for ctype, _, _, crc in results}
    assert by_type == {"IHDR": True, "IDAT": False, "IEND": True}


def test_truncated_mid_chunk_raises_with_offset(png):
    for ctype, offset, length, _ in walk(png):
        if ctype == "IDAT":
            data_off = offset + 8
            break
    truncated = png[:data_off + length // 2]
    with pytest.raises(PngError) as excinfo:
        list(walk(truncated))
    assert excinfo.value.offset is not None


def test_parse_ihdr_fields(png):
    info = parse_ihdr(png)
    assert info["width"] == 3
    assert info["height"] == 2
    assert info["bit_depth"] == 8
    assert info["color_type"] == 2


def test_idat_decompresses_to_input_scanlines(png, rows):
    idat = None
    for ctype, offset, length, _ in walk(png):
        if ctype == "IDAT":
            idat = png[offset + 8:offset + 8 + length]
            break
    raw = zlib.decompress(idat)
    expected = b"".join(b"\x00" + row for row in rows)
    assert raw == expected


def test_bad_signature_raises():
    bad = b"\x00" * 8 + b"junk"
    with pytest.raises(PngError):
        list(walk(bad))


def test_offsets_point_at_type_fields(png):
    # first chunk's type starts right after the signature
    itype, ioff, _, _ = next(iter(walk(png)))
    assert ioff == 8
    assert png[ioff:ioff + 4] == b"IHDR"

